    templ=max([c for c in comps if len(c)>1 and any(v==3 for r,cc,v in [(r,cc,g[r][cc]) for r,cc in c])],key=len)
    tcells=[(r,cc,g[r][cc]) for r,cc in templ]
    tc=Counter(v for r,cc,v in tcells if v!=bg and v!=3)
    Tc=tc.most_common(1)[0][0] if tc else 4
    t3=[(r,cc) for r,cc in templ if g[r][cc]==3]
    assert len(t3)==1, t3
    tr_,tc_=t3[0]
    rels={(r-tr_,c-tc_) for r,c in templ}
    out=[row[:] for row in g]
    for c in comps:
        cells=[(r,cc,g[r][cc]) for r,cc in c]
        if len(c)==1 and v:=cells[0][2]:
            if v==3:
                for dr,dc in rels:
                    rr,ccv=tr_+dr,tc_+dc
                    if 0<=rr<H and 0<=ccv<W and g[rr][ccv]==bg:
                        out[rr][ccv]=Tc
            elif v==2:
                rr,ccv=cells[0][0]-1,cells[0][1]
                if 0<=rr<H and 0<=ccv<W and g[rr][ccv]==bg:
                    out[rr][ccv]=4
