        if len(c)<=1: continue
        cnt=C2(gi[p[0]][p[1]] for p in c)
        rare=min(cnt,key=lambda k:(cnt[k],k))
        anc=[p for p in c if gi[p[0]][p[1]]==rare][0]
        mr=min(p[0] for p in c); mc=min(p[1] for p in c)
        rel=[(p[0]-mr,p[1]-mc,gi[p[0]][p[1]]) for p in c]
        byrare.setdefault(rare,[]).append((anc,rel))
    marks={next(iter(c)):gi[next(iter(c))[0]][next(iter(c))[1]] for c in cs if len(c)==1}
    for m,v in marks.items():
        if v in byrare:
            for anc,rel in byrare[v]:
                dr,dc=m[0]-anc[0],m[1]-anc[1]
                for r,c_,val in rel:
                    rr,ccc=r+dr,c_+dc
                    if 0<=rr<H and 0<=ccc<W:
                        g[rr][ccc]=val
    return g
for i in (1,2,3,4,5):
    gi=G['Demo pair %d input'%i]; go=G['Demo pair %d output'%i]
    got=solve3(gi)
    dd=[(r,c,got[r][c],go[r][c]) for r in range(len(gi)) for c in range(len(gi[0])) if got[r][c]!=go[r][c]]
    print('demo',i,'ndiff',len(dd)); 
    if dd: print(dd[:10])

